// Prototype reconstruction of mapbox/earcut.hpp v2.2.4, arena-based.
const NIL: usize = usize::MAX;

#[derive(Clone, Copy)]
struct Node { i: u32, x: f64, y: f64, prev: usize, next: usize, z: i32, prev_z: usize, next_z: usize, steiner: bool }

struct E {
    n: Vec<Node>,
    indices: Vec<u32>,
    vertices: usize,
    hashing: bool,
    min_x: f64, max_x: f64, min_y: f64, max_y: f64,
    inv_size: f64,
    hole_filter_old: bool,
}

macro_rules! g { ($s:expr, $k:expr) => { $s.n[$k] } }

impl E {
    fn new(old: bool) -> E { E{ n: Vec::new(), indices: Vec::new(), vertices: 0, hashing: false,
        min_x:0.0, max_x:0.0, min_y:0.0, max_y:0.0, inv_size:0.0, hole_filter_old: old } }

    fn run(&mut self, points: &Vec<Vec<(f64,f64)>>) {
        self.indices.clear(); self.vertices = 0;
        if points.is_empty() { return; }
        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i = 0usize;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }
        let _ = len;
        let mut outer = self.linked_list(&points[0], true);
        if outer == NIL { return; }
        if g!(self, outer).prev == g!(self, outer).next { return; }
        if points.len() > 1 { outer = self.eliminate_holes(points, outer); }
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = g!(self, outer).next;
            self.min_x = g!(self, outer).x; self.max_x = self.min_x;
            self.min_y = g!(self, outer).y; self.max_y = self.min_y;
            loop {
                let (x,y) = (g!(self,p).x, g!(self,p).y);
                if x < self.min_x { self.min_x = x } if y < self.min_y { self.min_y = y }
                if x > self.max_x { self.max_x = x } if y > self.max_y { self.max_y = y }
                p = g!(self,p).next;
                if p == outer { break }
            }
            let s = f64::max(self.max_x - self.min_x, self.max_y - self.min_y);
            self.inv_size = if s != 0.0 { 32767.0 / s } else { 0.0 };
        }
        self.earcut_linked(outer, 0);
    }

    fn linked_list(&mut self, points: &Vec<(f64,f64)>, clockwise: bool) -> usize {
        let mut sum = 0.0f64;
        let len = points.len();
        let mut last = NIL;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = points[i]; let p2 = points[j];
            sum += (p2.0 - p1.0) * (p1.1 + p2.1);
            j = i;
        }
        if clockwise == (sum > 0.0) {
            for i in 0..len { let v = self.vertices + i; let p = points[i]; last = self.insert_node(v, p, last); }
        } else {
            for i in (0..len).rev() { let v = self.vertices + i; let p = points[i]; last = self.insert_node(v, p, last); }
        }
        if last != NIL {
            let nx = g!(self,last).next;
            if self.equals(last, nx) { self.remove_node(last); last = g!(self,last).next; }
        }
        self.vertices += len;
        last
    }

    fn filter_points(&mut self, start: usize, end0: usize) -> usize {
        if start == NIL { return NIL }
        let mut end = if end0 == NIL { start } else { end0 };
        let mut p = start;
        loop {
            let mut again = false;
            let (pv, nx) = (g!(self,p).prev, g!(self,p).next);
            if !g!(self,p).steiner && (self.equals(p, nx) || self.area(pv, p, nx) == 0.0) {
                self.remove_node(p);
                p = g!(self,p).prev; end = p;
                if p == g!(self,p).next { break }
                again = true;
            } else { p = g!(self,p).next; }
            if !(again || p != end) { break }
        }
        end
    }

    fn earcut_linked(&mut self, mut ear: usize, pass: i32) {
        if ear == NIL { return }
        if pass == 0 && self.hashing { self.index_curve(ear); }
        let mut stop = ear;
        while g!(self,ear).prev != g!(self,ear).next {
            let prev = g!(self,ear).prev; let next = g!(self,ear).next;
            let ok = if self.hashing { self.is_ear_hashed(ear) } else { self.is_ear(ear) };
            if ok {
                self.indices.push(g!(self,prev).i);
                self.indices.push(g!(self,ear).i);
                self.indices.push(g!(self,next).i);
                self.remove_node(ear);
                ear = g!(self,next).next; stop = g!(self,next).next;
                continue;
            }
            ear = next;
            if ear == stop {
                if pass == 0 { let f = self.filter_points(ear, NIL); self.earcut_linked(f, 1); }
                else if pass == 1 {
                    let f = self.filter_points(ear, NIL);
                    let e2 = self.cure_local_intersections(f);
                    self.earcut_linked(e2, 2);
                } else if pass == 2 { self.split_earcut(ear); }
                break;
            }
        }
    }

    fn is_ear(&self, ear: usize) -> bool {
        let a = g!(self,ear).prev; let b = ear; let c = g!(self,ear).next;
        if self.area(a,b,c) >= 0.0 { return false }
        let mut p = g!(self, g!(self,ear).next).next;
        while p != g!(self,ear).prev {
            let (pv, nx) = (g!(self,p).prev, g!(self,p).next);
            if self.pit(g!(self,a).x,g!(self,a).y,g!(self,b).x,g!(self,b).y,g!(self,c).x,g!(self,c).y,g!(self,p).x,g!(self,p).y)
                && self.area(pv,p,nx) >= 0.0 { return false }
            p = g!(self,p).next;
        }
        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = g!(self,ear).prev; let b = ear; let c = g!(self,ear).next;
        if self.area(a,b,c) >= 0.0 { return false }
        let (ax,ay,bx,by,cx,cy)=(g!(self,a).x,g!(self,a).y,g!(self,b).x,g!(self,b).y,g!(self,c).x,g!(self,c).y);
        let min_tx = ax.min(bx.min(cx)); let min_ty = ay.min(by.min(cy));
        let max_tx = ax.max(bx.max(cx)); let max_ty = ay.max(by.max(cy));
        let min_z = self.z_order(min_tx, min_ty); let max_z = self.z_order(max_tx, max_ty);
        let mut p = g!(self,ear).next_z;
        while p != NIL && g!(self,p).z <= max_z {
            let (pv,nx)=(g!(self,p).prev, g!(self,p).next);
            if p != g!(self,ear).prev && p != g!(self,ear).next
                && self.pit(ax,ay,bx,by,cx,cy,g!(self,p).x,g!(self,p).y) && self.area(pv,p,nx) >= 0.0 { return false }
            p = g!(self,p).next_z;
        }
        p = g!(self,ear).prev_z;
        while p != NIL && g!(self,p).z >= min_z {
            let (pv,nx)=(g!(self,p).prev, g!(self,p).next);
            if p != g!(self,ear).prev && p != g!(self,ear).next
                && self.pit(ax,ay,bx,by,cx,cy,g!(self,p).x,g!(self,p).y) && self.area(pv,p,nx) >= 0.0 { return false }
            p = g!(self,p).prev_z;
        }
        true
    }

    fn cure_local_intersections(&mut self, start0: usize) -> usize {
        if start0 == NIL { return NIL }
        let mut start = start0; let mut p = start;
        loop {
            let a = g!(self,p).prev; let b = g!(self, g!(self,p).next).next;
            let pn = g!(self,p).next;
            if !self.equals(a,b) && self.intersects(a,p,pn,b) && self.locally_inside(a,b) && self.locally_inside(b,a) {
                self.indices.push(g!(self,a).i); self.indices.push(g!(self,p).i); self.indices.push(g!(self,b).i);
                self.remove_node(p);
                let pn2 = g!(self,p).next;
                self.remove_node(pn2);
                p = b; start = b;
            }
            p = g!(self,p).next;
            if p == start { break }
        }
        self.filter_points(p, NIL)
    }

    fn split_earcut(&mut self, start: usize) {
        let mut a = start;
        loop {
            let mut b = g!(self, g!(self,a).next).next;
            while b != g!(self,a).prev {
                if g!(self,a).i != g!(self,b).i && self.is_valid_diagonal(a,b) {
                    let mut c = self.split_polygon(a,b);
                    let an = g!(self,a).next; let a2 = self.filter_points(a, an);
                    let cn = g!(self,c).next; c = self.filter_points(c, cn);
                    self.earcut_linked(a2, 0); self.earcut_linked(c, 0);
                    return;
                }
                b = g!(self,b).next;
            }
            a = g!(self,a).next;
            if a == start { break }
        }
    }

    fn eliminate_holes(&mut self, points: &Vec<Vec<(f64,f64)>>, mut outer: usize) -> usize {
        let mut queue: Vec<usize> = Vec::new();
        for i in 1..points.len() {
            let list = self.linked_list(&points[i], false);
            if list != NIL {
                if list == g!(self,list).next { self.n[list].steiner = true; }
                queue.push(self.get_leftmost(list));
            }
        }
        // std::sort with comparator a->x < b->x  (unstable, but n small)
        queue.sort_by(|&a, &b| self.n[a].x.partial_cmp(&self.n[b].x).unwrap());
        for k in 0..queue.len() {
            if self.hole_filter_old {
                self.eliminate_hole_old(queue[k], outer);
                let on = g!(self,outer).next;
                outer = self.filter_points(outer, on);
            } else {
                outer = self.eliminate_hole(queue[k], outer);
            }
        }
        outer
    }

    fn eliminate_hole(&mut self, hole: usize, outer: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer);
        if bridge == NIL { return outer }
        let br = self.split_polygon(bridge, hole);
        let brn = g!(self,br).next;
        self.filter_points(br, brn);
        let bn = g!(self,bridge).next;
        self.filter_points(bridge, bn)
    }

    fn eliminate_hole_old(&mut self, hole: usize, outer: usize) {
        let o = self.find_hole_bridge(hole, outer);
        if o != NIL {
            let b = self.split_polygon(o, hole);
            let bn = g!(self,b).next;
            self.filter_points(b, bn);
        }
    }

    fn find_hole_bridge(&self, hole: usize, outer: usize) -> usize {
        let mut p = outer;
        let hx = g!(self,hole).x; let hy = g!(self,hole).y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;
        loop {
            let pn = g!(self,p).next;
            if hy <= g!(self,p).y && hy >= g!(self,pn).y && g!(self,pn).y != g!(self,p).y {
                let x = g!(self,p).x + (hy - g!(self,p).y) * (g!(self,pn).x - g!(self,p).x) / (g!(self,pn).y - g!(self,p).y);
                if x <= hx && x > qx {
                    qx = x;
                    m = if g!(self,p).x < g!(self,pn).x { p } else { pn };
                    if x == hx { return m }
                }
            }
            p = g!(self,p).next;
            if p == outer { break }
        }
        if m == NIL { return NIL }
        let stop = m;
        let mx = g!(self,m).x; let my = g!(self,m).y;
        let mut tan_min = f64::INFINITY;
        p = m;
        loop {
            let px = g!(self,p).x; let py = g!(self,p).y;
            if hx >= px && px >= mx && hx != px
               && self.pit(if hy < my { hx } else { qx }, hy, mx, my, if hy < my { qx } else { hx }, hy, px, py) {
                let tan = (hy - py).abs() / (hx - px);
                if self.locally_inside(p, hole)
                   && (tan < tan_min || (tan == tan_min && (px > g!(self,m).x || (px == g!(self,m).x && self.sector_contains_sector(m,p))))) {
                    m = p; tan_min = tan;
                }
            }
            p = g!(self,p).next;
            if p == stop { break }
        }
        m
    }

    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(g!(self,m).prev, m, g!(self,p).prev) < 0.0 && self.area(g!(self,p).next, m, g!(self,m).next) < 0.0
    }

    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if g!(self,p).z == 0 { let (x,y)=(g!(self,p).x,g!(self,p).y); self.n[p].z = self.z_order(x,y); }
            self.n[p].prev_z = g!(self,p).prev;
            self.n[p].next_z = g!(self,p).next;
            p = g!(self,p).next;
            if p == start { break }
        }
        let pz = g!(self,p).prev_z;
        self.n[pz].next_z = NIL;
        self.n[p].prev_z = NIL;
        self.sort_linked(p);
    }

    fn sort_linked(&mut self, list0: usize) -> usize {
        let mut list = list0;
        let mut in_size = 1i32;
        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;
            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0i32;
                for _ in 0..in_size {
                    p_size += 1;
                    q = g!(self,q).next_z;
                    if q == NIL { break }
                }
                let mut q_size = in_size;
                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 { e = q; q = g!(self,q).next_z; q_size -= 1; }
                    else if q_size == 0 || q == NIL { e = p; p = g!(self,p).next_z; p_size -= 1; }
                    else if g!(self,p).z <= g!(self,q).z { e = p; p = g!(self,p).next_z; p_size -= 1; }
                    else { e = q; q = g!(self,q).next_z; q_size -= 1; }
                    if tail != NIL { self.n[tail].next_z = e } else { list = e }
                    self.n[e].prev_z = tail;
                    tail = e;
                }
                p = q;
            }
            self.n[tail].next_z = NIL;
            if num_merges <= 1 { return list }
            in_size *= 2;
        }
    }

    fn z_order(&self, xf: f64, yf: f64) -> i32 {
        let mut x = ((xf - self.min_x) * self.inv_size) as i32;
        let mut y = ((yf - self.min_y) * self.inv_size) as i32;
        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;
        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;
        x | (y << 1)
    }

    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start; let mut lm = start;
        loop {
            if g!(self,p).x < g!(self,lm).x || (g!(self,p).x == g!(self,lm).x && g!(self,p).y < g!(self,lm).y) { lm = p }
            p = g!(self,p).next;
            if p == start { break }
        }
        lm
    }

    fn pit(&self, ax:f64,ay:f64,bx:f64,by:f64,cx:f64,cy:f64,px:f64,py:f64) -> bool {
        (cx-px)*(ay-py)-(ax-px)*(cy-py) >= 0.0 &&
        (ax-px)*(by-py)-(bx-px)*(ay-py) >= 0.0 &&
        (bx-px)*(cy-py)-(cx-px)*(by-py) >= 0.0
    }

    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        g!(self, g!(self,a).next).i != g!(self,b).i && g!(self, g!(self,a).prev).i != g!(self,b).i
        && !self.intersects_polygon(a,b)
        && ((self.locally_inside(a,b) && self.locally_inside(b,a) && self.middle_inside(a,b)
             && (self.area(g!(self,a).prev, a, g!(self,b).prev) != 0.0 || self.area(a, g!(self,b).prev, b) != 0.0))
            || (self.equals(a,b) && self.area(g!(self,a).prev,a,g!(self,a).next) > 0.0
                && self.area(g!(self,b).prev,b,g!(self,b).next) > 0.0))
    }

    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (g!(self,q).y - g!(self,p).y) * (g!(self,r).x - g!(self,q).x)
        - (g!(self,q).x - g!(self,p).x) * (g!(self,r).y - g!(self,q).y)
    }

    fn equals(&self, a: usize, b: usize) -> bool { g!(self,a).x == g!(self,b).x && g!(self,a).y == g!(self,b).y }

    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1,q1,p2));
        let o2 = sign(self.area(p1,q1,q2));
        let o3 = sign(self.area(p2,q2,p1));
        let o4 = sign(self.area(p2,q2,q1));
        if o1 != o2 && o3 != o4 { return true }
        if o1 == 0 && self.on_segment(p1,p2,q1) { return true }
        if o2 == 0 && self.on_segment(p1,q2,q1) { return true }
        if o3 == 0 && self.on_segment(p2,p1,q2) { return true }
        if o4 == 0 && self.on_segment(p2,q1,q2) { return true }
        false
    }

    fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        g!(self,q).x <= f64::max(g!(self,p).x, g!(self,r).x) &&
        g!(self,q).x >= f64::min(g!(self,p).x, g!(self,r).x) &&
        g!(self,q).y <= f64::max(g!(self,p).y, g!(self,r).y) &&
        g!(self,q).y >= f64::min(g!(self,p).y, g!(self,r).y)
    }

    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = g!(self,p).next;
            if g!(self,p).i != g!(self,a).i && g!(self,pn).i != g!(self,a).i
               && g!(self,p).i != g!(self,b).i && g!(self,pn).i != g!(self,b).i
               && self.intersects(p,pn,a,b) { return true }
            p = g!(self,p).next;
            if p == a { break }
        }
        false
    }

    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = g!(self,a).prev; let an = g!(self,a).next;
        if self.area(ap,a,an) < 0.0 { self.area(a,b,an) >= 0.0 && self.area(a,ap,b) >= 0.0 }
        else { self.area(a,b,ap) < 0.0 || self.area(a,an,b) < 0.0 }
    }

    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a; let mut inside = false;
        let px = (g!(self,a).x + g!(self,b).x) / 2.0;
        let py = (g!(self,a).y + g!(self,b).y) / 2.0;
        loop {
            let pn = g!(self,p).next;
            if ((g!(self,p).y > py) != (g!(self,pn).y > py)) && g!(self,pn).y != g!(self,p).y
               && (px < (g!(self,pn).x - g!(self,p).x) * (py - g!(self,p).y) / (g!(self,pn).y - g!(self,p).y) + g!(self,p).x) {
                inside = !inside;
            }
            p = g!(self,p).next;
            if p == a { break }
        }
        inside
    }

    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.construct(g!(self,a).i, g!(self,a).x, g!(self,a).y);
        let b2 = self.construct(g!(self,b).i, g!(self,b).x, g!(self,b).y);
        let an = g!(self,a).next;
        let bp = g!(self,b).prev;
        self.n[a].next = b; self.n[b].prev = a;
        self.n[a2].next = an; self.n[an].prev = a2;
        self.n[b2].next = a2; self.n[a2].prev = b2;
        self.n[bp].next = b2; self.n[b2].prev = bp;
        b2
    }

    fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.n.push(Node{i,x,y,prev:NIL,next:NIL,z:0,prev_z:NIL,next_z:NIL,steiner:false});
        self.n.len()-1
    }

    fn insert_node(&mut self, i: usize, pt: (f64,f64), last: usize) -> usize {
        let p = self.construct(i as u32, pt.0, pt.1);
        if last == NIL { self.n[p].prev = p; self.n[p].next = p; }
        else {
            let ln = g!(self,last).next;
            self.n[p].next = ln;
            self.n[p].prev = last;
            self.n[ln].prev = p;
            self.n[last].next = p;
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let (pv, nx) = (g!(self,p).prev, g!(self,p).next);
        self.n[nx].prev = pv;
        self.n[pv].next = nx;
        let (pz, nz) = (g!(self,p).prev_z, g!(self,p).next_z);
        if pz != NIL { self.n[pz].next_z = nz }
        if nz != NIL { self.n[nz].prev_z = pz }
    }
}

fn sign(v: f64) -> i32 { ((0.0 < v) as i32) - ((v < 0.0) as i32) }

fn test2(n: i32, old: bool) -> String {
    let mut polygon: Vec<Vec<(f64,f64)>> = Vec::new();
    let nf = n as f64;
    polygon.push(vec![(0.0,0.0),(nf,0.0),(nf,nf),(0.0,nf)]);
    if n > 1 {
        polygon.push(vec![(0.25*nf,0.25*nf),(0.75*nf,0.25*nf),(0.75*nf,0.75*nf),(0.25*nf,0.75*nf)]);
    }
    let mut e = E::new(old);
    e.run(&polygon);
    let mut s = String::new();
    for idx in &e.indices { s.push_str(&idx.to_string()); s.push(' '); }
    s
}

fn main() {
